// Poll the Redis-backed pending approvals via a lightweight HTTP call
const raw = await $http.get(`${$env.SOAR_API_URL}/api/v1/iocs/stix`, {
  headers: { 'X-API-Key': $env.SOAR_API_KEY }
});

// Also fetch the SSE snapshot for pending_approvals
const eventsRes = await $http.get(`${$env.SOAR_API_URL}/health`);

// Return each pending approval as a separate item for downstream routing
const pendingRaw = $input.item.json.pending_approvals || {};
const items = [];
for (const [threadId, payloadStr] of Object.entries(pendingRaw)) {
  const payload = JSON.parse(payloadStr);
  items.push({ json: { ...payload, thread_id: threadId } });
}
return items.length > 0 ? items : [{ json: { no_pending: true } }];

